const DEFAULT_SORT = 'issued_date';
const DEFAULT_DIR = 'desc';

export default function App() {
  const [actors, setActors] = useState([]);
  const [actor, setActor] = useState(null);
  const [bootError, setBootError] = useState(null);

  const [courses, setCourses] = useState([]);
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [sortKey, setSortKey] = useState(DEFAULT_SORT);
  const [sortDir, setSortDir] = useState(DEFAULT_DIR);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);

  const [list, setList] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [selectedId, setSelectedId] = useState(null);
  const [exporting, setExporting] = useState(false);
  const [notice, setNotice] = useState(null);
  const [refreshKey, setRefreshKey] = useState(0);

  const listRequest = useRef(0);

  useEffect(() => {
    let cancelled = false;
    api
      .actors()
      .then((rows) => {
        if (cancelled) return;
        setActors(rows);
        if (rows.length > 0) {
          setActorToken(rows[0].token);
          setActor(rows[0]);
        }
      })
      .catch((err) => {
        if (!cancelled) setBootError(err.message);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search.trim());
      setPage(1);
    }, 250);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    if (!actor) return undefined;

    const requestId = listRequest.current + 1;
    listRequest.current = requestId;

    setLoading(true);
    setError(null);

    api
      .certificates({ q: debouncedSearch, sort: sortKey, dir: sortDir, page, pageSize })
      .then((data) => {
        if (listRequest.current !== requestId) return;
        setList(data);
        setLoading(false);
      })
      .catch((err) => {
        if (listRequest.current !== requestId) return;
        setError(err.message);
        setLoading(false);
      });

    return undefined;
  }, [actor, debouncedSearch, sortKey, sortDir, page, pageSize, refreshKey]);

  useEffect(() => {
    if (!actor) return undefined;
    let cancelled = false;
    api
      .courses()
      .then((rows) => {
        if (!cancelled) setCourses(rows);
      })
      .catch(() => {
        if (!cancelled) setCourses([]);
      });
    return () => {
      cancelled = true;
    };
  }, [actor, refreshKey]);

  const handleActorChange = (event) => {
    const next = actors.find((item) => item.token === event.target.value);
    if (!next) return;
    setActorToken(next.token);
    setActor(next);
    setList(null);
    setPage(1);
    setNotice(null);
    setError(null);
    setSelectedId(null);
  };

  const handleSort = (key) => {
    if (key === sortKey) {
      setSortDir((current) => (current === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir(key === 'issued_date' ? 'desc' : 'asc');
    }
    setPage(1);
  };

