      console.log(`   ? ${file}: ${[...new Set(m)].slice(0,3).join(' | ').slice(0,120)}`);
    }
  }
}
for (const [k,v] of Object.entries(counts)) console.log(`${k.padEnd(24)} ${v}`);
console.log(`\nfiles scanned: ${files.length}`);
EOF

